package cn.bidcheck.service;

import cn.bidcheck.domain.Domain.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class BusinessObligationIdentityTest {
    private Document tender(String... bodies){List<Page> pages=new ArrayList<>();for(int i=0;i<bodies.length;i++)pages.add(new Page(i+1,bodies[i],"PARAGRAPH","DOCX",""));return new Document("t","p","TENDER","tender.docx",1,"frozen-hash","",pages,List.of());}
    private Finding finding(String id,Document tender,int page,String expected){Page p=tender.pages().get(page-1);Evidence source=new Evidence("t","招标",p.number(),p.locationType(),p.text(),"p"+p.number(),1);Checkpoint cp=new Checkpoint(id,"同一展示标题","资格检查","HIGH","SEMANTIC_RESPONSE","qualification","RESPONDS",expected,"",true,true,true,source);return new Finding(id,"run",cp,new Evaluation("UNDETERMINED","待处理","",List.of(),0,"RULE"),Map.of());}
    private List<Map<String,Object>> groups(Document doc,int a,int b){return BusinessObligationGroups.summarize(List.of(finding("a",doc,a,doc.pages().get(a-1).text()),finding("b",doc,b,doc.pages().get(b-1).text())),doc);}
    @Test void controlledDocumentSynonymsMergeAcrossPagesWithBothSources(){Document d=tender("本项目不划分标段。","投标人资格要求","投标人须提交有效营业执照。","投标单位应提供有效的营业执照。");var groups=groups(d,3,4);assertEquals(1,groups.size());assertEquals(2,groups.get(0).get("sourceCount"));assertEquals("FROZEN_TENDER_EQUIVALENT",groups.get(0).get("mergeMethod"));assertEquals(false,groups.get(0).get("executionReusable"));assertEquals(true,groups.get(0).get("evidenceInvestigationReusable"));assertEquals(false,groups.get(0).get("businessDecisionReusable"));}
    @Test void membershipAndCompanySubjectsCannotMerge(){Document d=tender("本项目不划分标段。","投标人资格要求","设计单位资格要求","须提交有效营业执照。","施工单位资格要求","须提交有效营业执照。");assertEquals(2,groups(d,4,6).size());}
    @Test void inheritedDifferentLotsCannotMerge(){Document d=tender("投标人资格要求","第一标段资格要求","须提交有效营业执照。","第二标段资格要求","须提交有效营业执照。");assertEquals(2,groups(d,3,5).size());}
    @Test void unknownLotIsNotEqualToAnotherUnknownLot(){Document d=tender("投标人资格要求","须提交有效营业执照。","须提交有效营业执照。");assertEquals(2,groups(d,2,3).size());}
    @Test void qualificationAndScoringUseCannotMergeEvenWithSameBody(){Document d=tender("本项目不划分标段。","投标人资格要求","须提交质量管理体系认证证书。","评分标准","须提交质量管理体系认证证书。");assertEquals(2,groups(d,3,5).size());}
    @Test void namedProjectScopeCannotBeDiscarded(){Document d=tender("本项目不划分标段。","投标人资格要求","项目名称：项目甲。","须提交有效营业执照。","项目名称：项目乙。","须提交有效营业执照。");assertEquals(2,groups(d,4,6).size());}
    @Test void inheritedConsortiumExceptionRemainsPartOfIdentity(){Document d=tender("本项目不划分标段。","投标人资格要求","联合体各成员（新设单位除外）","须提供承诺书。","投标人资格要求","须提供承诺书。");assertEquals(2,groups(d,4,6).size());}
    @Test void explicitIndependentHeadingDoesNotCarryPreviousMemberRestriction(){Document d=tender("本项目不划分标段。","投标人资格要求","联合体各成员（新设单位除外）","须提供承诺书。","2.投标人资格要求","须提供承诺书。","投标人资格要求","须提供承诺书。");assertEquals(1,groups(d,6,8).size());assertEquals(2,groups(d,4,6).size());}
    @Test void sameShortExpectationCannotEraseExceptionFromOriginal(){Document d=tender("本项目不划分标段。","投标人资格要求","须提供承诺书，新设单位除外。","须提供承诺书。");Finding a=finding("a",d,3,"须提供承诺书"),b=finding("b",d,4,"须提供承诺书");assertEquals(2,BusinessObligationGroups.summarize(List.of(a,b),d).size());}
    @Test void orAndNegationAndTaxRemainDifferent(){for(String[] pair:List.of(new String[]{"提交甲证或乙证","提交甲证且乙证"},new String[]{"含税报价不得超过100元","不含税报价不得超过100元"},new String[]{"须提供承诺书","不得提供承诺书"})){Document d=tender("本项目不划分标段。","投标人资格要求",pair[0],pair[1]);assertEquals(2,groups(d,3,4).size());}}
    @Test void sourceMismatchAndRepeatedQuoteAreNotMergeable(){Document d=tender("本项目不划分标段。","投标人资格要求","须提供承诺书。","别的原文");Finding a=finding("a",d,3,"须提供承诺书"),b=finding("b",d,4,"须提供承诺书");assertEquals(2,BusinessObligationGroups.summarize(List.of(a,b),d).size());}
    @Test void englishIdentifiersAndNumericPunctuationArePreserved(){for(String[] pair:List.of(new String[]{"证书编号 AB C","证书编号 ABC"},new String[]{"证书编号1 00","证书编号100"},new String[]{"1.2万元","12万元"},new String[]{"2.2.1版证书","2.2.2版证书"})){assertNotEquals(BusinessObligationIdentity.normalize(pair[0]),BusinessObligationIdentity.normalize(pair[1]));Document d=tender("本项目不划分标段。","投标人资格要求",pair[0],pair[1]);assertEquals(2,groups(d,3,4).size());}}
    @Test void explicitCountSynonymsPreserveSameThreshold(){Document d=tender("本项目不划分标段。","投标人资格要求","专职安全员至少1名。","专职安全员不少于1人。");assertEquals(1,groups(d,3,4).size());}
    @Test void mandatoryFlagsRemainDistinct(){Document d=tender("本项目不划分标段。","投标人资格要求","须提供承诺书。","须提供承诺书。");Finding a=finding("a",d,3,"须提供承诺书"),b=finding("b",d,4,"须提供承诺书");Checkpoint cp=b.checkpoint();b=new Finding(b.id(),b.runId(),new Checkpoint(cp.id(),cp.title(),cp.category(),cp.severity(),cp.type(),cp.field(),cp.operator(),cp.expected(),cp.unit(),false,true,true,cp.source()),b.evaluation(),b.assessment());assertEquals(2,BusinessObligationGroups.summarize(List.of(a,b),d).size());}
    @Test void bodyFromSameTableCanKeepIndependentRequirements(){Document d=tender("本项目不划分标段。","投标人资格要求","人员要求\t项目负责人1人。 / （1）项目负责人资格要求：须提供注册证书。","人员要求：项目负责人1人。");Finding a=finding("a",d,3,"人员要求\t项目负责人1人。"),b=finding("b",d,4,"人员要求：项目负责人1人。");assertEquals(1,BusinessObligationGroups.summarize(List.of(a,b),d).size());var certificate=finding("c",d,3,"项目负责人资格要求：须提供注册证书。");assertEquals(2,BusinessObligationGroups.summarize(List.of(a,certificate),d).size());}
    @Test void explicitSampleUndividedStatementDoesNotCreateProjectScope(){Document d=tender("填写示例","本项目不划分标段。","投标人资格要求","须提供承诺书。","须提供承诺书。");assertEquals(2,groups(d,4,5).size());}
    @Test void stableGroupDoesNotDependOnFindingIdsOrInputOrder(){Document d=tender("本项目不划分标段。","投标人资格要求","须提供承诺书。","须提供承诺书。");var first=groups(d,3,4).get(0).get("id");var second=BusinessObligationGroups.summarize(List.of(finding("new-b",d,4,"须提供承诺书"),finding("new-a",d,3,"须提供承诺书")),d).get(0).get("id");assertEquals(first,second);}
    @Test void nullFrozenDocumentKeepsLegacyBoundary(){Document d=tender("本项目不划分标段。","投标人资格要求","须提供承诺书。","须提供承诺书。");assertEquals(2,BusinessObligationGroups.summarize(List.of(finding("a",d,3,"须提供承诺书"),finding("b",d,4,"须提供承诺书")),null).size());}
    @Test void truncatedCitationCannotDropFrozenClauseException(){Document d=tender("本项目不划分标段。","投标人资格要求","须提供承诺书，新设单位除外。","须提供承诺书。");Finding original=finding("a",d,3,"须提供承诺书");Checkpoint c=original.checkpoint();Evidence source=new Evidence("t","招标",3,"PARAGRAPH","须提供承诺书","",1);Finding shortened=new Finding("a","run",new Checkpoint(c.id(),c.title(),c.category(),c.severity(),c.type(),c.field(),c.operator(),c.expected(),c.unit(),c.required(),c.enabled(),c.confirmed(),source),original.evaluation(),Map.of());assertEquals(2,BusinessObligationGroups.summarize(List.of(shortened,finding("b",d,4,"须提供承诺书")),d).size());}
    @Test void circledListLineWrapMayNormalizeButOrProofAndConstructionRemainBound(){String body="设计单位资质要求：须满足下列条件之一：①甲证。②乙证。须提交有效证明文件。";Document d=tender("本项目不划分标段。","投标人资格要求","2.2.1"+body.replace("①","\n①").replace("②","\n②"),"资质要求\t（1）"+body.replace("须提交有效证明文件。"," / 须提交有效证明文件。")+" / （2）施工单位资质要求：须提供丙证。");assertEquals(1,BusinessObligationGroups.summarize(List.of(finding("a",d,3,body),finding("b",d,4,body)),d).size());assertNotEquals(BusinessObligationIdentity.normalize(body),BusinessObligationIdentity.normalize(body.replace("之一","全部")));assertNotEquals(BusinessObligationIdentity.normalize(body),BusinessObligationIdentity.normalize(body.replace("须提交有效证明文件。","")));}
}
